spawn.example:
const { Quaternion, Vector3 } = kcds.math;

const facingEast = Quaternion.fromEuler(0, 0, Math.PI / 2);
kcds.world.SiegeLadder.spawn('siege', new Vector3(100, 200, 10), facingEast);

kcds.core.Events.on('siegeLadderUse', (player, ladder, action) => {
  return action !== 'push' || player.dimension === 0;
});

spawn.exampleCs:
var facingEast = Quaternion.FromEuler(0, 0, Math.PI / 2);
SiegeLadder.Spawn("siege", new Vector3(100, 200, 10), facingEast);

Events.On("siegeLadderUse", object? (Player player, JsValue ladder, JsValue action) =>
{
    return action.AsString() != "push" || player.Dimension == 0;
});
